DROP SCHEMA IF EXISTS midterm_expense CASCADE;
CREATE SCHEMA midterm_expense;
CREATE TABLE midterm_expense.staging_employees (raw_row_id BIGSERIAL PRIMARY KEY, emp_id TEXT, emp_name TEXT, department TEXT, role TEXT, bank_account TEXT, address TEXT, approval_limit_thb TEXT, active_flag TEXT, source_file TEXT DEFAULT 'employees.csv', ingested_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE midterm_expense.staging_vendors (raw_row_id BIGSERIAL PRIMARY KEY, vendor_id TEXT, vendor_name TEXT, category TEXT, owner_name TEXT, bank_account TEXT, address TEXT, registration_date TEXT, risk_country TEXT, active_flag TEXT, source_file TEXT DEFAULT 'vendors.csv', ingested_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE midterm_expense.staging_invoices (raw_row_id BIGSERIAL PRIMARY KEY, invoice_id TEXT, invoice_number TEXT, vendor_id TEXT, employee_id TEXT, approver_id TEXT, invoice_date TEXT, amount_thb TEXT, description TEXT, po_id TEXT, payment_method TEXT, currency TEXT, source_file TEXT DEFAULT 'invoices.csv', ingested_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE midterm_expense.production_employees (LIKE midterm_expense.staging_employees INCLUDING DEFAULTS, approval_limit_numeric NUMERIC(14,2), row_hash TEXT, load_batch_id TEXT);
CREATE TABLE midterm_expense.production_vendors (LIKE midterm_expense.staging_vendors INCLUDING DEFAULTS, registration_date_typed DATE, row_hash TEXT, load_batch_id TEXT);
CREATE TABLE midterm_expense.production_invoices (raw_row_id BIGINT, invoice_id TEXT PRIMARY KEY, invoice_number TEXT, vendor_id TEXT, employee_id TEXT, approver_id TEXT, invoice_date DATE, amount_thb NUMERIC(14,2), description TEXT, po_id TEXT, payment_method TEXT, currency TEXT, source_file TEXT, ingested_at TIMESTAMPTZ, row_hash TEXT, load_batch_id TEXT);
CREATE TABLE midterm_expense.quarantine (source_table TEXT, row_key TEXT, reason TEXT, raw_record JSONB, quarantined_at TIMESTAMPTZ DEFAULT NOW());
-- Revision: dedicated classroom schema only; running setup resets this case.
CREATE TABLE midterm_expense.landing_files(upload_id TEXT PRIMARY KEY,source_table TEXT,expected_rows BIGINT,source_file TEXT,file_size BIGINT,content_base64 TEXT,file_hash TEXT,ingested_at TIMESTAMPTZ DEFAULT NOW(),loaded_by TEXT DEFAULT CURRENT_USER);
ALTER TABLE midterm_expense.staging_employees ADD COLUMN upload_id TEXT;
ALTER TABLE midterm_expense.staging_vendors ADD COLUMN upload_id TEXT;
ALTER TABLE midterm_expense.staging_invoices ADD COLUMN upload_id TEXT;
ALTER TABLE midterm_expense.production_employees ADD COLUMN upload_id TEXT;
ALTER TABLE midterm_expense.production_vendors ADD COLUMN upload_id TEXT;
ALTER TABLE midterm_expense.production_invoices ADD COLUMN upload_id TEXT;
ALTER TABLE midterm_expense.staging_employees ADD COLUMN loaded_by TEXT DEFAULT CURRENT_USER;
ALTER TABLE midterm_expense.staging_vendors ADD COLUMN loaded_by TEXT DEFAULT CURRENT_USER;
ALTER TABLE midterm_expense.staging_invoices ADD COLUMN loaded_by TEXT DEFAULT CURRENT_USER;
ALTER TABLE midterm_expense.production_employees ADD COLUMN loaded_by TEXT;
ALTER TABLE midterm_expense.production_vendors ADD COLUMN loaded_by TEXT;
ALTER TABLE midterm_expense.production_invoices ADD COLUMN loaded_by TEXT;
CREATE UNIQUE INDEX ON midterm_expense.production_employees(emp_id);
CREATE UNIQUE INDEX ON midterm_expense.production_vendors(vendor_id);
CREATE INDEX ON midterm_expense.production_invoices(vendor_id,invoice_date);
CREATE INDEX ON midterm_expense.production_invoices(employee_id);
CREATE OR REPLACE FUNCTION midterm_expense.promote(p JSONB) RETURNS JSONB LANGUAGE plpgsql AS $$
DECLARE b TEXT := 'MIDTERM-' || to_char(clock_timestamp(),'YYYYMMDDHH24MISSUS');
BEGIN
 TRUNCATE midterm_expense.production_employees,midterm_expense.production_vendors,midterm_expense.production_invoices,midterm_expense.quarantine;
 INSERT INTO midterm_expense.production_employees SELECT (jsonb_populate_record(NULL::midterm_expense.production_employees,v || jsonb_build_object('approval_limit_numeric',v->'approval_limit_thb','row_hash',md5(v::text),'load_batch_id',b))).* FROM jsonb_array_elements(p->'employees') v;
 INSERT INTO midterm_expense.production_vendors SELECT (jsonb_populate_record(NULL::midterm_expense.production_vendors,v || jsonb_build_object('registration_date_typed',v->'registration_date','row_hash',md5(v::text),'load_batch_id',b))).* FROM jsonb_array_elements(p->'vendors') v;
 INSERT INTO midterm_expense.production_invoices SELECT (jsonb_populate_record(NULL::midterm_expense.production_invoices,v || jsonb_build_object('row_hash',md5(v::text),'load_batch_id',b))).* FROM jsonb_array_elements(p->'invoices') v;
 INSERT INTO midterm_expense.quarantine(source_table,row_key,reason,raw_record) SELECT v->>'source_table',v->>'row_key',v->>'reason',v->'raw_record' FROM jsonb_array_elements(p->'quarantine') v;
 RETURN jsonb_build_object('load_batch_id',b,'status','promoted');
END $$;

