function welchTest(a,b){const base={method:'Welch independent two-sample t-test',n_a:a.length,n_b:b.length,mean_a:mean(a),mean_b:mean(b),t:null,df:null,p_value:null,significant:false};if(a.length<2||b.length<2)return{...base,status:'insufficient_data'};const av=variance(a)/a.length,bv=variance(b)/b.length;if(av+bv<=0)return{...base,status:'zero_variance'};const t=(mean(a)-mean(b))/Math.sqrt(av+bv),df=(av+bv)**2/(av**2/(a.length-1)+bv**2/(b.length-1));const p=betaRegularized(df/(df+t*t),df/2,.5);return{...base,status:'ok',t,df,p_value:p,significant:p<.05};}
