function scanBreakpoints(rows,min=4){const s=[...rows].sort((a,b)=>a.invoice_date.localeCompare(b.invoice_date)||a.invoice_id.localeCompare(b.invoice_id));const tests=[];for(let k=min;k<=s.length-min;k++){if(s[k-1].invoice_date===s[k].invoice_date)continue;const r=welchTest(s.slice(0,k).map(x=>x.amount_thb),s.slice(k).map(x=>x.amount_thb));if(r.status==='ok')tests.push({...r,split_date:s[k].invoice_date,n_old:k,n_new:s.length-k});}for(const r of tests){r.adjusted_p_value=Math.min(1,r.p_value*tests.length);r.significant=r.adjusted_p_value<.05;}tests.sort((a,b)=>a.adjusted_p_value-b.adjusted_p_value);return{method:'Exploratory transaction-amount breakpoint scan with Welch tests',correction:'Bonferroni within the target-vendor scan',minimum_transactions_per_side:min,test_count:tests.length,best:tests[0]??null,candidates:tests,limitations:'Transactions may be correlated within monthly purchase clusters. P-values are approximate screening evidence, not independent proof of fraud.'};}
